using Finora.Domain;namespace Finora.UnitTests;public sealed class DomainRulesTests{[Fact]public void MonthlyRecurrence_ClampsToEndOfMonth(){var r=new RecurrenceRule{Name="Month end",Frequency=RecurrenceFrequency.Monthly,DayOfMonth=31,StartsOn=new DateOnly(2026,1,31),TransactionType=TransactionType.Expense,AmountMinor=100,AccountId=Guid.NewGuid()};Assert.Equal(new DateOnly(2026,2,28),DomainRules.GetNextOccurrence(r,r.StartsOn));}[Fact]public void TransactionSplits_MustEqualTransactionAmount(){var tx=new FinanceTransaction{Type=TransactionType.Expense,AmountMinor=-1000,Currency="INR",AccountId=Guid.NewGuid(),OccurredAtUtc=DateTimeOffset.UtcNow,Splits=[new TransactionSplit{AmountMinor=-900}]};Assert.Throws<InvalidOperationException>(()=>DomainRules.ValidateTransaction(tx));}}
